#include <stdio.h>
#include <ctype.h>

static int roman_digit_value(char c)
{
    switch (toupper((unsigned char)c)) {
        case 'I': return 1;
        case 'V': return 5;
        case 'X': return 10;
        case 'L': return 50;
        case 'C': return 100;
        case 'D': return 500;
        case 'M': return 1000;
        default:  return -1;
    }
}

int main(void)
{
    char text[1024];

    if (scanf("%1023s", text) != 1) {
        return 0;
    }

    long long value = 0;
    size_t i = 0;

    while (text[i] != '\0') {
        int current = roman_digit_value(text[i]);
        if (current < 0) {
            fprintf(stderr, "Invalid Roman numeral: %c\n", text[i]);
            return 1;
        }

        if (text[i + 1] != '\0') {
            int next = roman_digit_value(text[i + 1]);
            if (next < 0) {
                fprintf(stderr, "Invalid Roman numeral: %c\n", text[i + 1]);
                return 1;
            }
            if (current < next) {
                value -= current;
            } else {
                value += current;
            }
        } else {
            value += current;
        }

        ++i;
    }

    printf("%lld\n", value);
    return 0;
}
