            if (new_cap < cap || new_cap > MAX_INPUT + 1) {
                new_cap = MAX_INPUT + 1;
            }
            char *tmp = realloc(buf, new_cap);
            if (tmp == NULL) {
                fail("out of memory");
            }
            buf = tmp;
            cap = new_cap;
        }
        buf[len++] = (char)c;
    }

    if (ferror(stdin)) {
        fail("read error");
    }

    buf[len] = '\0';
    if (memchr(buf, '\0', len) != NULL) {
        fail("invalid input");
