        fail("negative integers are not supported");
    }
    if (*p == '+') {
        ++p;
    }
    if (!isdigit((unsigned char)*p)) {
        fail("expected an integer");
    }

    char *end = NULL;
    errno = 0;
    unsigned long long value = strtoull(p, &end, 10);
    if (errno == ERANGE) {
        fail("integer out of range");
    }
    if (end == p) {
        fail("expected an integer");
    }

    while (isspace((unsigned char)*end)) {
        ++end;
    }
    if (*end != '\0') {
        fail("trailing data after integer");
    }

    char out[sizeof(value) * CHAR_BIT + 2];
    size_t oi = 0;

    if (value == 0) {
        out[oi++] = '0';
    } else {
        int started = 0;
        for (int i = (int)(sizeof(value) * CHAR_BIT) - 1; i >= 0; --i) {
            if ((value >> i) & 1ULL) {
                started = 1;
                out[oi++] = '1';
            } else if (started) {
                out[oi++] = '0';
            }
        }
    }

    out[oi++] = '\n';
    out[oi] = '\0';

    if (fputs(out, stdout) == EOF || fflush(stdout) != 0) {
        fail("write error");
    }

    free(buf);
    return 0;
}
